function trk_icon(string $name, string $class = 'h-4 w-4'): string
{
    $paths = TRK_ICONS[$name] ?? TRK_ICONS['info'];
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
        . ' stroke-linecap="round" stroke-linejoin="round" class="shrink-0 ' . $class . '" aria-hidden="true" focusable="false">'
        . $paths . '</svg>';
}
